.chapter-content {
  min-width: 0;
  max-width: 100%;
  color: var(--text);
  font-family: var(--reader-font);
  font-size: var(--reader-size);
  line-height: var(--reader-leading);
  line-break: strict;
  word-break: normal;
  overflow-wrap: break-word;
  text-spacing-trim: trim-start;
}
.chapter-content .chapter-title {
  margin: 0 0 24px;
  font-size: 1.6em;
  font-weight: 600;
  line-height: 1.25;
  text-align: center;
  text-indent: 0;
  break-after: avoid;
}
.chapter-content p {
  margin: 0;
  text-indent: 2em;
  text-align: justify;
  line-break: strict;
  word-break: normal;
  overflow-wrap: break-word;
  text-spacing-trim: trim-start;
  line-height: var(--reader-leading);
  orphans: 2;
  widows: 2;
}
.chapter-content .dateline,
.chapter-content .scene-break {
  margin: 24px 0;
  color: var(--muted);
  text-align: center;
  text-indent: 0;
}
.chapter-content .dateline {
  margin-top: 0;
  font-size: 0.85em;
}
.chapter-content hr.rule {
  width: 32%;
  margin: 32px auto;
  border: 0;
  border-top: 1px solid var(--border);
}
.chapter-content blockquote {
  margin: 24px 0;
  padding-inline: 20px;
  border-inline-start: 3px solid var(--border);
}
.chapter-content .dialog { padding-block: 4px; }
.chapter-content .dialog.railed {
  border-inline-start: 3px solid currentColor;
  padding-inline-start: 16px;
}
.chapter-content ul,
.chapter-content ol {
  margin-block: 16px;
  padding-inline-start: 2em;
}
.chapter-content li {
  padding-inline-start: 4px;
  text-indent: 0;
}
.chapter-content li + li { margin-top: 4px; }
.chapter-content sup,
.chapter-content sub {
  position: relative;
  font-size: 0.7em;
  line-height: 0;
  vertical-align: baseline;
}
.chapter-content sup { top: -0.5em; }
.chapter-content sub { bottom: -0.2em; }
.chapter-content code {
  font-family: ui-monospace, "SFMono-Regular", Consolas, monospace;
  font-size: 0.9em;
  overflow-wrap: anywhere;
}
.chapter-content b,
.chapter-content strong { font-weight: 700; }
.chapter-content em { font-style: italic; }
.chapter-content figure.fig {
  box-sizing: border-box;
  max-width: 100%;
  margin: 24px auto;
  padding: 8px;
  overflow: auto;
  border-radius: var(--figure-radius);
  background: var(--terminal-bg);
  color: var(--terminal-text);
  text-align: center;
  text-indent: 0;
  break-inside: avoid;
}
.chapter-content figure.fig img {
  display: block;
  max-width: 100%;
  height: auto;
  margin-inline: auto;
  object-fit: contain;
}
.chapter-content figure.fig figcaption {
  padding: 8px 4px 0;
  font: 0.75em/1.5 var(--font-sans);
  text-align: center;
}
.device-view {
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  margin: 24px auto;
  padding: 16px;
  overflow-x: auto;
  border-radius: var(--radius);
  background: var(--terminal-bg);
  color: var(--terminal-text);
  color-scheme: dark;
  font-family: ui-monospace, "SFMono-Regular", Consolas, monospace;
  font-size: 0.85em;
  line-height: 1.7;
  text-align: start;
  text-indent: 0;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--terminal-text) var(--terminal-bg);
  break-inside: avoid;
}
.wide-device-view { width: 100%; }
.device-view-left { margin-inline: 0 auto; text-align: start; }
.chapter-content .device-view p {
  text-indent: 0;
  text-align: start;
  line-height: inherit;
}
.device-view table {
  width: 100%;
  border-collapse: collapse;
  font: inherit;
  text-align: start;
}
.device-view th,
.device-view td {
  padding: 8px 12px;
  border: 1px solid var(--terminal-text);
  text-align: start;
  vertical-align: top;
  overflow-wrap: anywhere;
}
.device-view thead {
  background: var(--terminal-text);
  color: var(--terminal-bg);
}
.device-view input[type="range"] {
  box-sizing: border-box;
  display: block;
  width: 100%;
  min-width: 0;
  min-height: 44px;
  margin: 4px 0;
  accent-color: var(--terminal-text);
}
.device-view input[type="range"]:disabled { opacity: 1; }
.device-view button {
  min-height: 44px;
  max-width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--terminal-text);
  border-radius: var(--figure-radius);
  background: var(--terminal-bg);
  color: var(--terminal-text);
  font: inherit;
  white-space: normal;
}
.device-view button:disabled,
.device-view button[aria-disabled="true"] {
  opacity: 1;
  cursor: default;
  box-shadow: none;
  transform: none;
}
.device-view [style*="display"][style*="flex"] {
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding-block: 8px;
}
.device-view [style*="display"][style*="flex"] > span {
  flex: 0 1 auto;
  align-self: center;
  max-width: 100%;
  white-space: nowrap;
  line-height: 1.5;
}
.dz-script {
  font-family: Georgia, "Palatino Linotype", "Songti SC", cursive, serif;
  font-style: italic;
  letter-spacing: 0.04em;
}
.dz-card {
  box-sizing: border-box;
  max-width: 100%;
  margin: 24px 0;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  overflow-wrap: anywhere;
  break-inside: avoid;
}

/* 视口高度由阅读布局确定；flow 的一列正好等于视口宽度。 */
html[data-page-mode="paged"] .reader-viewport {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  scrollbar-width: none;
}
html[data-page-mode="paged"] .reader-flow {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-width: 0;
  margin: 0;
  column-count: 1;
  column-width: auto;
  column-gap: 32px;
  column-fill: auto;
  overflow: visible;
  transform-origin: left top;
  transition: none;
}
html[data-page-mode="paged"] .reader-flow > .chapter-content {
  height: 100%;
}
html[data-page-mode="paged"] .reader-flow figure.fig,
html[data-page-mode="paged"] .reader-flow .device-view,
html[data-page-mode="paged"] .reader-flow .dz-card {
  max-height: 100%;
  margin-block: 0;
  overflow: auto;
  break-inside: avoid;
}
html[data-page-mode="paged"] .reader-flow figure.fig img {
  max-height: 100%;
  object-fit: contain;
}
html[data-page-mode="paged"] .reader-viewport::-webkit-scrollbar {
  display: none;
}
/* 内部终端仍保留滚动提示，不隐藏其滚动条。 */
@media (max-width: 768px) {
  .chapter-content .chapter-title { font-size: 1.45em; }
  .chapter-content blockquote { padding-inline: 12px; }
  .chapter-content figure.fig { width: 100%; padding: 4px; }
  .chapter-content figure.fig img { width: 100%; }
  .device-view { padding: 12px; }
  .device-view th, .device-view td { padding: 8px; }
  html:not([data-js]) .chapter-content {
    font-size: 18px;
    line-height: 1.8;
  }
  html:not([data-js]) .chapter-content p { line-height: 1.8; }
}

html:not([data-js]) body.reader-page { overflow: auto; height: auto; }
html:not([data-js]) #reader-main {
  display: block;
  height: auto;
  max-height: none;
  overflow: visible;
}
html:not([data-js]) #pane-zh {
  display: block;
  width: 100%;
  max-width: 38em;
  height: auto;
  margin-inline: auto;
  overflow: visible;
}
html:not([data-js]) #pane-en,
html:not([data-js]) #lang-tabs,
html:not([data-js]) #bottombar,
html:not([data-js]) #drawer,
html:not([data-js]) #settings-panel,
html:not([data-js]) #scrim { display: none; }
html:not([data-js]) #reader-main .reader-viewport,
html:not([data-js]) #reader-main .reader-flow,
html:not([data-js]) #reader-main .chapter-content {
  height: auto;
  max-height: none;
  overflow: visible;
  columns: auto;
  transform: none;
}
html:not([data-js]) #reader-main figure.fig,
html:not([data-js]) #reader-main .device-view,
html:not([data-js]) #reader-main .dz-card { max-height: none; }

@media print {
  html, html body { height: auto; overflow: visible; background: none; color: black; }
  #topbar, #bottombar, #progress-bar, #lang-tabs, #chapter-nav,
  #drawer, #settings-panel, #scrim, .skip-link,
  body.reader-page button, body.reader-page input,
  body.reader-page select, body.reader-page textarea { display: none !important; }
  html #reader-main {
    display: flex;
    flex-direction: column;
    position: static;
    width: auto;
    height: auto;
    margin: 0;
    padding: 0;
    overflow: visible;
  }
  html #reader-main [data-lang],
  html #reader-main .reader-viewport,
  html #reader-main .reader-flow,
  html #reader-main .chapter-content {
    position: static;
    width: auto;
    max-width: none;
    height: auto !important;
    max-height: none;
    margin: 0;
    padding: 0;
    overflow: visible;
    columns: auto;
    transform: none !important;
    contain: none;
    background: none;
    color: black;
  }
  html #reader-main #pane-zh { display: block; order: 2; }
  html #reader-main #pane-en { display: none; order: 1; }
  html[data-js][data-lang-mode="en"] #reader-main #pane-zh { display: none; }
  html[data-js][data-lang-mode="en"] #reader-main #pane-en,
  html[data-js][data-lang-mode="dual"] #reader-main #pane-en { display: block; }
  html[data-js][data-lang-mode="dual"] #reader-main #pane-zh { display: block; }
  html #reader-main figure.fig, html #reader-main .device-view,
  html #reader-main .dz-card {
    max-height: none;
    overflow: visible;
    background: none;
    color: black;
    box-shadow: none;
    break-inside: auto;
  }
  html #reader-main figure.fig img { max-height: none; }
  .device-view thead { background: none; color: black; }
  .device-view th, .device-view td { border-color: currentColor; }
  .chapter-content .chapter-title { break-after: avoid; }
}
